export interface ReportTrend {
  /** the metric's key, from analysis/profile.py. Stable across versions; the label is not. (max 80 chars) */
  metric: string;
  /** the metric in words a person reads, from the one table in analysis/trends.py. (max 80 chars) */
  label: string;
  /** its value over the older of the two equal windows. */
  before: number;
  /** its value over the newer window. */
  now: number;
  /** the signed relative change, (now - before) / before. 0.7 is up 70 percent. */
  move: number;
  /** up, down, or steady. Steady is a real answer: under the noise floor is not a move. */
  direction: TrendDirection;
  /** whether this direction is the one they want, when the metric has a direction at all. Null means the change is reported with no verdict: more hours is not better and a night owl is not broken. */
  good?: boolean | null;
  /** sittings in the older window. Both windows need a sample or there is no trend. */
  sessions_before: number;
  /** sittings in the newer window. */
  sessions_now: number;
}

export interface ReportAgentType {
  /** the subagent type, one of the harness's own (analysis/agents.py BUILTIN_AGENT_TYPES); unknown when the sidecar never said, and custom for every name somebody gave their own agent, which is free text and never leaves the machine. */
  name: AgentType;
  /** how many instances of that type ran. */
  agents: number;
}

export interface ReportAgents {
  /** subagent instances that ran in the window. Counted from sidecar transcripts, which every other tool skips. */
  agents: number;
  /** how many of them did anything at all: a tool call, a file, an error. An agent that produced nothing is a delegation that cost tokens and returned air. */
  produced: number;
  /** the most that were running at the same moment. A handoff is not two agents at once, so an end sorts before a start at equal timestamps. */
  max_concurrent: number;
  /** the sum of every agent's own span. Deliberately larger than wall time when they overlap; that overlap is the point. */
  agent_seconds: number;
  /** clock time from the first agent starting to the last one stopping. */
  wall_seconds: number;
  /** how much of that stretch had at least one agent running. The union of the spans, so an overlap counts once. */
  busy_seconds: number;
  /** agent_seconds over busy_seconds: while agents were running, how many were running at once. 1.0 is a queue, 3.4 is three and a bit at a time. Never below 1.0 when anything ran, which is why the denominator is the union and not the stretch. */
  parallelism: number;
  /** the split by subagent type, most common first. (max 12 items) */
  by_type: ReportAgentType[];
}

export interface ReportDay {
  /** the day, YYYY-MM-DD, with the 04:00 boundary this repository uses everywhere else. (max 80 chars) */
  day: string;
  /** commits that landed while an agent was working. */
  assisted: number;
  /** commits that landed outside every session window. Deliberately generous: anything the capture never saw counts here. */
  alone: number;
}

export interface ReportContributions {
  /** commits with an agent in the room. */
  assisted: number;
  /** commits you wrote on your own. */
  alone: number;
  /** days you shipped something. Not days you opened the app: a streak a tab can extend is a streak about the tab. */
  active_days: number;
  /** the longest run of consecutive shipping days. */
  longest_streak: number;
  /** the run ending today or yesterday. Yesterday still counts, because today is not over. */
  current_streak: number;
  /** one entry per day that had a commit, oldest first. Days with none are absent rather than zero rows. (max 400 items) */
  days: ReportDay[];
}

export interface ReportGreen {
  /** how many times a failing test run was followed by a passing one. */
  n: number;
  /** the median of those recoveries. The solo builder's answer to DORA's mean time to restore. */
  median_seconds: number;
  /** the longest one. */
  worst_seconds: number;
  /** how many runs it typically took to get back to green. */
  median_attempts: number;
}

export interface ReportQuality {
  /** test runs seen in the window, counted from shell commands. */
  runs: number;
  /** runs with no error after them. */
  passed?: number | null;
  /** runs an error followed. */
  failed?: number | null;
  /** the share of test runs that were already green. Not 'the first try worked' per feature, which nothing here can see. */
  first_try_rate?: number | null;
  /** the recovery numbers, or null when nothing in the window failed and then passed. */
  time_to_green?: ReportGreen | null;
  /** why the rates are null, when they are. Present only on a refusal. (max 200 chars) */
  reason?: string | null;
}

export interface ReportPrompting {
  /** prompts long enough to be an instruction rather than a nudge. */
  attempts: number;
  /** of those, how many landed something without a correction and without the agent stalling. */
  clean?: number | null;
  /** how many cost a correction or a long stall. */
  costly?: number | null;
  /** clean over attempts. NO PROMPT TEXT TRAVELS: this is the whole of what the playbook uploads. */
  clean_share?: number | null;
  /** why the share is null, when it is. (max 200 chars) */
  reason?: string | null;
}

export interface ReportLanguage {
  /** the language, from a fixed table of extensions. `other` is an extension nobody mapped, counted rather than guessed at. (max 80 chars) */
  name: string;
  /** lines the agent added in it. */
  lines: number;
  /** distinct files. A count, never a name: paths do not leave the machine. */
  files: number;
  /** its share of the attributable lines. */
  share: number;
}

export interface ReportLanguages {
  /** attributable lines in the window, generated files already excluded. */
  lines: number;
  /** lines nobody wrote: lockfiles, `node_modules`, this repository's own generated Swift, TypeScript and Python. Reported rather than hidden, because a silent exclusion is indistinguishable from a parser that missed the file. */
  generated_lines_excluded: number;
  /** most lines first, the tail summed into `other`. Null when there were too few attributable lines to split. (max 12 items) */
  languages?: ReportLanguage[] | null;
  /** why the split is null, when it is. (max 200 chars) */
  reason?: string | null;
}

export interface ReportCoverage {
  /** the window that was ASKED FOR. Repeated from the top level so this block is readable on its own. */
  window_days: number;
  /** the calendar distance from the first sitting on this machine to the last. NOT the same as days built: two sittings a month apart span 30 days and are 2 active days. */
  spans_days: number;
  /** days that actually had a sitting. */
  active_days: number;
  /** sittings the numbers above rest on. */
  sessions: number;
  /** the earliest sitting found. Null when there are none. (ISO 8601) */
  first_at?: string | null;
  /** the latest. (ISO 8601) */
  last_at?: string | null;
}

export interface ReportArchetypeScore {
  /** the archetype a rule names, from analysis/profile.py ARCHETYPE_RULES. */
  name: Archetype;
  /** the metric that rule reads. */
  metric: ArchetypeMetric;
  /** the metric's value on this corpus. Null when it could not be computed. */
  value?: number | null;
  /** the value the rule needs to win, from ARCHETYPE_RULES. Null when the sender left it out. */
  threshold?: number | null;
  /** value over threshold, capped at 2 and halved, a fraction: meeting the threshold exactly scores 0.5. Null when value is. (0-1) */
  score?: number | null;
}

export interface ReportKindCount {
  /** a kind of change, as a commit subject labels it (wrapped.classify_subject). */
  kind: CommitKind;
  /** commits whose subject says this kind. */
  commits: number;
}

export interface ReportRoleLines {
  /** a file role from analysis/plain.py role_of: the path's shape, never its contents. */
  role: PlainRole;
  /** agent lines added to project files of this role. */
  lines: number;
}

export interface ReportWrappedExtras {
  /** builder_type: the archetype's confidence, a fraction: its margin over the runner up, damped below ten sessions. (0-1) */
  confidence?: number | null;
  /** builder_type: the metric behind the winning rule. */
  metric?: ArchetypeMetric | null;
  /** builder_type: that metric's value, the number its sentence says. */
  metric_value?: number | null;
  /** builder_type: true when that metric's basis says it is a floor, so the sentence says at least. */
  metric_lower_bound?: boolean | null;
  /** builder_type, generalist only: the rule that came nearest. */
  closest?: ReportArchetypeScore | null;
  /** builder_type: the next rules by score. (max 2 items) */
  runners_up?: ReportArchetypeScore[] | null;
  /** shipped: distinct commits git log found across every repository these sessions ran in. kind_of_work: commit subjects read. */
  commits?: number | null;
  /** shipped: of those, commits inside a session window or the lookback before one. */
  assisted?: number | null;
  /** shipped: the rest of them. */
  alone?: number | null;
  /** shipped: how the commits were counted. Null when no commit history was read. */
  commits_basis?: CommitsBasis | null;
  /** work_style: the share of active time the agent ran with nobody present. (0-1) */
  autonomy?: number | null;
  /** work_style: median prompts over sessions with you there. */
  median_prompts?: number | null;
  /** work_style: interrupts plus corrections over prompts. A number and not a fraction, because interrupts can outnumber prompts. */
  steer_rate?: number | null;
  /** longest_session: that session's active seconds, beside the attended seconds in value. */
  active_seconds?: number | null;
  /** longest_session: when it started. (ISO 8601) */
  started_at?: string | null;
  /** agents_at_once: the most helper agents running at one moment across the corpus. */
  subagents_peak?: number | null;
  /** agents_at_once: helper agents that ran. */
  subagents?: number | null;
  /** go_to_prompt: distinct sessions the prompt was sent in. */
  sessions?: number | null;
  /** go_to_prompt: its length in words. A count, never the words. */
  words?: number | null;
  /** streak: days with a commit. */
  commit_days?: number | null;
  /** streak: days with a session you were there for. */
  attended_days?: number | null;
  /** streak: days with both, the only days a streak can run over. */
  both_days?: number | null;
  /** change_course: interrupts counted. */
  interrupts?: number | null;
  /** change_course: prompts that corrected the agent. */
  corrective_prompts?: number | null;
  /** prompt_length: median words a prompt. prompts_per_session: median prompts a session. */
  median?: number | null;
  /** deep_sessions: average minutes with you there across the deep sessions. */
  avg_minutes?: number | null;
  /** deep_sessions: the longest session with you there, in whole minutes, floored. */
  longest_minutes?: number | null;
  /** time_put_in: hours with you there. */
  attended_hours?: number | null;
  /** time_put_in: at most this many of the attended hours are counted twice, because sessions ran at the same time. Its sentence says so when it is above 0. */
  attended_overlap_hours?: number | null;
  /** prompts_per_session: tool calls over prompts, across the sessions the card counts. */
  tool_calls_per_prompt?: number | null;
  /** kind_of_work: labelled commits by kind, in wrapped.KINDS order, kinds with none left out. (max 10 items) */
  kinds?: ReportKindCount[] | null;
  /** kind_of_work: commit subjects that say what kind of change they are. */
  classified?: number | null;
  /** kind_of_work: the share of subjects read that carry a label. (0-1) */
  coverage?: number | null;
  /** kind_of_work: agent lines by file role, in plain.ROLES order, roles with none left out. (max 9 items) */
  role_lines?: ReportRoleLines[] | null;
  /** kind_of_work: why the commit labels could not decide the card, when they could not. */
  commit_refusal?: KindRefusal | null;
  /** kind_of_work: attributable lines the file role fallback read. */
  lines?: number | null;
  /** kind_of_work: the lines that fallback needs (languages.MIN_LINES). */
  lines_needed?: number | null;
}

